args.ReplacementContent:
    {/* Shows Only Toggle */}
    <button
      type="button"
      onClick={() => setShowTourDatesOnly(prev => !prev)}
      className={`px-3 py-1.5 border text-xs font-bold rounded-lg shadow-sm transition-colors cursor-pointer border-solid flex items-center gap-1.5 ${
        showTourDatesOnly 
          ? 'border-amber-500/40 bg-amber-500/15 text-amber-400' 
          : 'border-white/10 bg-black/40 hover:bg-white/5 text-white/70 hover:text-white'
      }`}
      title="Show only days with tour shows"
    >
      {showTourDatesOnly ? '🎸 SHOWS ONLY' : 'ALL DAYS'}
    </button>

    {/* Capacity Heatmap Toggle */}
    <button
      type="button"
      onClick={() => setShowCapacityHeatmap(prev => !prev)}
      className={`px-3 py-1.5 border text-xs font-bold rounded-lg shadow-sm transition-colors cursor-pointer border-solid flex items-center gap-1.5 ${
        showCapacityHeatmap
          ? 'border-rose-500/40 bg-rose-500/15 text-rose-400'
          : 'border-white/10 bg-black/40 hover:bg-white/5 text-white/70 hover:text-white'
      }`}
      title="Toggle team availability & capacity workload heatmaps"
    >
      🔥 {showCapacityHeatmap ? 'HEATMAP ON' : 'HEATMAP'}
    </button>

    {/* Crew Member Filter */}
    <div className="relative">
      <select
        value={scheduleCrewFilter}
        onChange={(e) => setScheduleCrewFilter(e.target.value)}
        className="appearance-none pr-8 pl-3 py-1.5 border border-white/10 bg-black/40 hover:bg-white/5 text-xs font-bold text-white/70 hover:text-white rounded-lg shadow-sm transition-colors cursor-pointer outline-none border-solid min-w-[140px]"
      >
        <option value="">👥 All Crew</option>
        {crewMembers.filter(m => m.id !== 'openshifts').map(member => (
          <option key={member.id} value={member.id}>{member.name}</option>
        ))}
      </select>
      <div className="absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none text-white/30">
        <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9" /></svg>
      </div>
    </div>

  </div>


</div>
{/* Grid Body */}
<div className="p-4 bg-black/10 min-w-0 space-y-4">
  {showCapacityHeatmap && (
    <div className="flex items-center gap-4 bg-[#141419] border border-white/5 rounded-xl px-4 py-2.5 text-[10px] font-extrabold uppercase tracking-wider text-white/50 animate-[fadeIn_0.2s_ease] w-fit">
      <span className="text-white/30 font-bold">Capacity Heatmap:</span>
      <div className="flex items-center gap-1.5">
        <span className="w-2.5 h-2.5 rounded-full bg-rose-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]"></span>
        <span className="text-white/70">Overloaded (> 100%)</span>
      </div>
      <div className="flex items-center gap-1.5">
        <span className="w-2.5 h-2.5 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]"></span>
        <span className="text-white/70">Optimal (50% - 100%)</span>
      </div>
      <div className="flex items-center gap-1.5">
        <span className="w-2.5 h-2.5 rounded-full bg-sky-500 shadow-[0_0_8px_rgba(14,165,233,0.5)]"></span>
        <span className="text-white/70">Underutilized (< 50%)</span>
      </div>
    </div>
  )}
  {renderRosterBoard()}

